extern void __global_pointer$();

pcb_t pcb[NUM_MAX_TASK];
pcb_t kernel_pcb[NR_CPUS];
const pcb_t *core0_tp = &kernel_pcb[0];
const pcb_t *core1_tp = &kernel_pcb[1];
const ptr_t kernel_stack_0 = INIT_KERNEL_STACK + PAGE_SIZE;
const ptr_t kernel_stack_1 = INIT_KERNEL_STACK + 2 * PAGE_SIZE;

LIST_HEAD(ready_queue);
LIST_HEAD(sleep_queue);

/* current running task PCB */
pcb_t * volatile current_running[NR_CPUS];
pcb_t * volatile current_cpu_running;

/* global process id */
pid_t process_id = 2;

/* at most this many arguments are handed over to a new process */
#define MAX_EXEC_ARGC 16

/*
 * A brand new address space costs a few frames right away (the ELF image, the
 * first stack page and the kernel stack).  Refuse to exec instead of running
 * into an allocation that cannot be satisfied even by swapping.
 */
#define EXEC_MIN_FREE_PAGES 16

static void destroy_task(pcb_t *task, int still_on_kernel_stack);

/*
 * A task cannot be destroyed while it is running: its page table is installed
 * in `satp` and it is standing on its own kernel stack.  do_kill() and
 * do_exit() therefore only mark the victim here, and the hart it runs on
 * finishes the job on its way out of scheduler().  The mark lives outside the
 * pcb because `status` is overwritten by every do_block().
 */
static pcb_t * volatile pending_kill[NR_CPUS];

/*
 * A task released with AUTO_CLEANUP_ON_EXIT is handed to the idle task of
 * core 0, which frees its kernel stack -- the very stack the dying task is
 * still standing on while it unwinds out of the kernel.  Publishing it one
 * scheduling round later gives it all the time it needs to leave.
 */
static pcb_t * volatile pending_reap[NR_CPUS];

/*
 * Only modify PCB, current_running, process_id and ready_queue
 * DO NOT STORE OR RESTORE
 * trick: modify $tp in ret_from_exception to ensure
 * disable_preempt() and enable_preempt() modify the same PCB
 */
void scheduler(void)
{
    pcb_t *prev = current_running[cpu_id];
    pcb_t *next;
    pcb_t *dying = NULL;
    list_node_t *next_node;

    /* the task torn down one round ago has left its kernel stack by now */
    if (pending_reap[cpu_id] != NULL) {
        list_add_tail(&pending_reap[cpu_id]->list, &kernel_pcb[0].wait_list);
        pending_reap[cpu_id] = NULL;
    }

    if (prev != &kernel_pcb[cpu_id]) {
        if (pending_kill[cpu_id] == prev) {
            pending_kill[cpu_id] = NULL;
            dying = prev;
        } else if (prev->status == TASK_RUNNING) {
            /* still runnable: back to the tail of the ready queue */
            prev->status = TASK_READY;
            prev->ready_tick = get_ticks();
            list_add_tail(&prev->list, &ready_queue);
        }
    }

    next_node = max_priority_node();
    if (next_node == NULL) {
        /* nothing this hart may run, go back to its idle task */
        next = &kernel_pcb[cpu_id];
    } else {
        list_del(next_node);
        next = list_entry(next_node, pcb_t, list);
    }

    next->status = TASK_RUNNING;
    next->cpu_id = cpu_id;
    current_running[cpu_id] = next;
    /* ret_from_exception restores the context of `current_cpu_running` */
    current_cpu_running = next;

    /* every task owns its own cursor position */
    screen_cursor_x[cpu_id] = next->cursor_x;
    screen_cursor_y[cpu_id] = next->cursor_y;

    /* install the address space of the new task; the kernel window is part
     * of every page table, so the code below keeps running just fine */
    set_satp(SATP_MODE_SV39, 0, ((uintptr_t)next->pgdir) >> NORMAL_PAGE_SHIFT);
    local_flush_tlb_all();

    /* now that we no longer run inside it, the old address space may go */
    if (dying != NULL) {

    slot[argc] = 0;

    uintptr_t argv_va = sp;
    /* the RISC-V ABI wants a 16 byte aligned stack pointer */
    new_pcb->user_sp = ROUNDDOWN(sp, 16);
    *argc_io = argc;

    #undef STACK_KVA
    return argv_va;
}

/*
 * Load the ELF image called `file_name` into a brand new address space and
 * make it a runnable process.  The return value is the one the shell expects:
 * -1 when there is no such program, 0 when the process table is full, -2 when
 * memory ran out and the new pid on success.
 */
pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
{
    disable_preempt();
    /* file_name and argv live in the caller's user space */
    enable_sum();

    unsigned char *binary = NULL;
    int length = 0;
    if (file_name == NULL || !get_elf_file(file_name, &binary, &length)) {
        disable_sum();
        enable_preempt();
        return -1;
    }

    /* clamp once, so that the array built on the user stack and the `argc`
     * handed to main() can never disagree */
    if (argc < 0 || argv == NULL) {
        argc = 0;
    }
    if (argc > MAX_EXEC_ARGC) {
        argc = MAX_EXEC_ARGC;
    }

    /* look for a free pcb: `pid == -1` marks an unused slot */
    int i;
    for (i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == -1) {
            break;
        }
    }
    if (i == NUM_MAX_TASK) {
        disable_sum();
        enable_preempt();
        return 0;
    }

    if (free_page_num() < EXEC_MIN_FREE_PAGES) {
        disable_sum();
        enable_preempt();
        return -2;
    }

    pcb_t *new_pcb = &pcb[i];
    new_pcb->pgdir = init_page_table();
    /* the kernel stack is a pinned physical page used through the direct map */
    new_pcb->kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
    new_pcb->kernel_stack_base = new_pcb->kernel_sp;
    new_pcb->user_sp = USER_STACK_ADDR;
    new_pcb->user_stack_base = USER_STACK_ADDR;
    new_pcb->preempt_count = 0;
    init_list_head(&new_pcb->wait_list);
    init_list_head(&new_pcb->timer.list);
    new_pcb->binsem_num = 0;
    new_pcb->pid = process_id++;
    new_pcb->type = USER_PROCESS;
    new_pcb->status = TASK_READY;
    new_pcb->mode = mode;
    new_pcb->priority = 1;
    new_pcb->ready_tick = get_ticks();
    /* a child may run wherever its parent was allowed to run */
    new_pcb->mask = current_running[cpu_id]->mask;
    if (new_pcb->mask == 0) {
        new_pcb->mask = (1UL << NR_CPUS) - 1;
    }
    new_pcb->cpu_id = cpu_id;
    new_pcb->cursor_x = 1;
    new_pcb->cursor_y = 1;

    uintptr_t entry = load_elf(binary, (unsigned)length,
                               (uintptr_t)new_pcb->pgdir, alloc_page_helper);
    uintptr_t argv_va = init_user_stack(new_pcb, &argc, argv);

    init_pcb_stack(new_pcb->kernel_sp, new_pcb->user_sp, entry,
                   new_pcb, argc, argv_va);
    list_add_tail(&new_pcb->list, &ready_queue);

    pid_t new_pid = new_pcb->pid;
    disable_sum();
    enable_preempt();
    return new_pid;
}

/* Give up every binary semaphore `task` still holds and hand each of them to
 * the next waiter, so that nobody stays blocked on a dead process. */
static void release_binsem(pcb_t *task)
{
    while (task->binsem_num > 0) {
        int id = task->binsem_id[--task->binsem_num];
        binsem_node_t *node = &binsem_nodes[id];

        node->sem++;
        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
            list_node_t *heir_node = node->block_queue.next;
            pcb_t *heir = list_entry(heir_node, pcb_t, list);
            heir->binsem_id[heir->binsem_num++] = id;
            do_unblock(heir_node);
        }
    }
}

/*
 * A task that dies while queued on a binary semaphore has already spent the
 * `sem--` of its pending acquire.  Give that count back, otherwise the next
 * release would believe somebody is still waiting and hand the lock to the
 * head of an empty queue.
 */
static void abandon_binsem_wait(pcb_t *task)
{
    for (int i = 0; i < BINSEM_NUMBER; i++) {
        binsem_node_t *node = &binsem_nodes[i];
        list_node_t *p;
        for (p = node->block_queue.next; p != &node->block_queue; p = p->next) {
            if (p == &task->list) {
                list_del(p);
                node->sem++;
                return;
            }
        }
    }
}

/* Common part of exiting and being killed: hand back the semaphores, wake
 * everybody who waits for this task and disarm its sleep timer. */
static void release_resources(pcb_t *task)
{
    release_binsem(task);
    abandon_binsem_wait(task);

    while (!list_empty(&task->wait_list)) {
        do_unblock(task->wait_list.next);
    }

    /* a sleeping task may still have an armed timer */
    list_del(&task->timer.list);
}

/*
 * Destroy `task` completely: give back everything it holds, throw away its
 * address space and mark the pcb.  The kernel stack survives a little longer,
 * because a task that has just stopped running is still standing on it: it is
 * released either by the parent in do_waitpid() or by the idle task of core 0.
 */
static void destroy_task(pcb_t *task, int still_on_kernel_stack)
{
    release_resources(task);

    free_process_user_page(task->pgdir);
    task->pgdir = (PTE*)PGDIR_PA;

    list_del(&task->list);

    if (task->mode == ENTER_ZOMBIE_ON_EXIT) {
        /* the parent reaps us in do_waitpid() */
        task->status = TASK_ZOMBIE;
    } else {
        task->status = TASK_EXITED;
        if (still_on_kernel_stack) {
            /* it is still unwinding out of the kernel: let the idle task of
             * core 0 have it only after the next scheduling round */
            pending_reap[cpu_id] = task;
        } else {
            list_add_tail(&task->list, &kernel_pcb[0].wait_list);
        }
    }
}

void do_exit()
{
    disable_preempt();
    pcb_t *cur = current_running[cpu_id];

    /* We still run in this address space and on this kernel stack, so the
     * teardown has to wait until scheduler() has switched away from us. */
    list_del(&cur->list);
    pending_kill[cpu_id] = cur;
    scheduler();

    enable_preempt();
}

// sleep(seconds)
void do_sleep(uint32_t sleep_time)
{
    // 1. block the current_running
    // 2. create a timer which calls `do_unblock` when timeout
    // 3. reschedule because the current_running is blocked
    do_block(&current_running[cpu_id]->list, &sleep_queue);
    list_node_t* parameter = &current_running[cpu_id]->list;
    timer_create((TimerCallback)do_unblock, (void*)parameter, get_ticks() + time_base * sleep_time);
    scheduler();
}

/* the pcb of a live task with this pid, or NULL */
static pcb_t *find_pcb(pid_t pid)
{
    if (pid < 0) {
        /* -1 is the free-slot marker, never a real process */
        return NULL;
    }
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == pid) {
            return &pcb[i];
        }
    }
    return NULL;
}

int do_kill(pid_t pid)
{
    disable_preempt();

    pcb_t *victim = find_pcb(pid);
    int already_dying = 0;
    for (int i = 0; i < NR_CPUS; i++) {
        if (victim != NULL && pending_kill[i] == victim) {
            already_dying = 1;
        }
    }
    if (victim == NULL || already_dying ||
        victim->status == TASK_EXITED || victim->status == TASK_ZOMBIE) {
        enable_preempt();
        return 0;
    }

    if (victim == current_running[cpu_id]) {
        /* killing ourselves is just an exit */
        enable_preempt();
        do_exit();
        return 1;
    }

    if (victim->status == TASK_RUNNING) {
        /* It is running on the other hart: its page table is installed there
         * and it may still be inside a critical section, so nothing may be
         * taken away yet.  That hart destroys it when it next reschedules. */
        pending_kill[victim->cpu_id] = victim;
    } else {
        /* ready or blocked: nobody is executing it, tear it down right now */
        destroy_task(victim, 0);
    }

    enable_preempt();
    return 1;
}

/*
 * A blocked process can only be resumed in user mode, so waitpid cannot
 * simply continue where it left off.  Instead the caller is blocked on the
 * child's wait list and `sepc` is rewound onto the `ecall`, so once the child
 * exits the system call is executed again -- this time finding the child
 * gone (or a zombie ready to be reaped).  The return value has to be `pid`
 * in that case because handle_syscall() writes it back into a0, which is the
 * very argument the retried `ecall` will pick up.
 */
int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
{
    disable_preempt();

    pcb_t *child = find_pcb(pid);

    if (child == NULL) {
        /* already gone and cleaned up */
        enable_preempt();
        return 0;
    }

    if (child->status == TASK_ZOMBIE || child->status == TASK_EXITED) {
        /* reap it: release the kernel stack and free the pcb slot */
        free_user_page(kva2pa(child->kernel_stack_base - PAGE_SIZE));
        list_del(&child->list);
        child->status = TASK_EXITED;
        child->pid = -1;
        enable_preempt();
        return 1;
    }

    /* still alive: sleep on it and retry the system call when woken up */
    regs->sepc = regs->sepc - 4;
    do_block(&current_running[cpu_id]->list, &child->wait_list);
    scheduler();

    enable_preempt();
    return pid;
}

